"""Authored v1.0 source; never reads model answers. Run only before freezing."""
import json
from pathlib import Path
from decimal import Decimal, ROUND_HALF_UP
ROOT = Path(__file__).resolve().parents[1]
ROWS = []

def add(category, scenario, expected, operation=None, operands=None):
    n = sum(r['category'] == category for r in ROWS) + 1
    row = dict(id=f'{category}-{n:02}', category=category, question=scenario,
               human_reference=expected, numeric=None, subjective_scores=None)
    if operation:
        a = list(map(Decimal, operands))
        value = {'subtract': lambda: a[0]-sum(a[1:]), 'sum': lambda: sum(a),
                 'multiply': lambda: a[0]*a[1], 'divide': lambda: a[0]/a[1],
                 'percent': lambda: a[0]/a[1]*100}[operation]()
        row['numeric'] = dict(operation=operation, operands=operands,
                              expected=str(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)),
                              tolerance='0.01', unit='percent' if operation == 'percent' else 'USD')
        row['question'] += '\nGive practical advice and show the arithmetic. End with exactly one line ANSWER_AMOUNT: <number> for the requested amount (no currency symbol, rounded to two decimals), followed by exactly one line ANSWER_UNIT: ' + row['numeric']['unit']
    ROWS.append(row)

add('budgeting', 'I take home $3,180 monthly. Rent is $1,240, utilities $185, groceries $420, transport $165, insurance $110, and minimum debt payments $210. I also want to reserve $300 for savings. What amount remains for all other spending, and how can I keep irregular bills from disrupting this plan?', 'Remaining $550; distinguish flexible spending from irregular-bill sinking funds; do not treat the remainder as entirely free money.', 'subtract', ['3180','1240','185','420','165','110','210','300'])
add('budgeting', 'My monthly take-home pay is $2,460. My current plan is rent $1,050, utilities $190, food $360, commute $145, childcare $500, minimum debt $180, subscriptions $65, and saving $100. What is the signed monthly balance (income minus all listed allocations)? Help me revise it without casually assuming I can drop childcare.', 'Balance -$130; preserve childcare and essentials; examine subscriptions, flexible costs and savings temporarily without recommending missed minimums.', 'subtract', ['2460','1050','190','360','145','500','180','65','100'])
add('budgeting', 'I freelance and netted $1,900, $3,100 and $2,300 in my last three months. Essential bills total $1,750 monthly, and taxes are already set aside. Should I build next month\'s spending plan around the best month? Explain a workable buffer and low-income-month rule.', 'Use conservative baseline, not best month; smooth variable income with a buffer; distinguish three observations from a reliable forecast.')
add('budgeting', 'I am paid $1,340 every two weeks, exactly 26 payments per year. What is my annual take-home pay? Explain why treating every month as two paychecks can help routine budgeting even though it understates annual income.', 'Annual $34,840; most months two checks; extra-check months can fund irregular expenses; no claim every month has identical income.', 'multiply', ['1340','26'])
add('budgeting', 'My car insurance of $780 is due six months from today. Nothing is saved yet, and I can make six equal monthly deposits before it is due. Ignoring interest, how much per month should I reserve? Where should this money sit in my budget?', 'Monthly $130, earmarked accessible sinking fund rather than emergency savings.', 'divide', ['780','6'])
add('budgeting', 'My partner and I share $1,800 of monthly household bills. We agree to split them in proportion to net incomes of $2,400 and $3,600. What is my share if I earn $2,400? Suggest one way to revisit this arrangement fairly.', 'Share $720 based on 40%; proportional split is an agreed convention not universal fairness; revisit on income changes.', 'multiply', ['1800','0.4'])
add('budgeting', 'My budget app says I overspent because it counted my $600 transfer from checking to savings as spending and my $240 credit-card payment again after recording each purchase. How should I categorize these movements without making real purchases disappear?', 'Transfer is not consumption; avoid double counting card principal already categorized as purchases; interest/fees are expenses; reconcile balances.')
add('budgeting', 'I have $295 left in this week\'s food-and-transit envelope. A necessary transit pass costs $72 and a planned grocery shop costs $138. What amount remains after both? Suggest a realistic guardrail before buying an optional $95 jacket.', 'Remaining $85, so jacket exceeds remaining envelope by $10 and would leave no buffer; defer or explicitly reallocate.', 'subtract', ['295','72','138'])
add('budgeting', 'I am a student sharing housing. My friend says a 50/30/20 budget is mandatory, but rent and basic food already use 68% of my take-home pay. I feel I have failed. How should I adapt a budget while my income is fixed this semester?', 'Heuristic not requirement; empathetic prioritization of essentials, small buffer, supports and feasible adjustments; no moral judgment.')
add('budgeting', 'I net $4,100 monthly and currently spend $3,620 including minimum debt payments. I want to add $350 to an emergency fund and $200 to a holiday fund each month. What is the signed amount left after both new goals? Help prioritize without counting credit-card borrowing as income.', 'Balance -$70; sequence or reduce goals, prioritize resilience and debt obligations; borrowing is not income.', 'subtract', ['4100','3620','350','200'])

add('saving', 'My essential expenses are $1,850 monthly. I want an emergency reserve covering three months and already have $1,100 saved. What additional amount is needed? Explain why this is a starting target rather than a guarantee of enough protection.', 'Additional $4,450; total target $5,550; adjust for job stability/dependents and keep liquid.', 'subtract', ['5550','1100'])
add('saving', 'A replacement laptop for work will cost $960 in eight months. I have $160 specifically saved and will make eight deposits before buying it. With no interest, what monthly deposit reaches the goal?', 'Monthly $100; do not count emergency savings twice.', 'divide', ['800','8'])
add('saving', 'My bank advertises 4.2% APY on a savings account. I deposit $2,500, leave it untouched for exactly one year, and assume the APY stays unchanged with no fees or tax. What interest will I earn? Distinguish APY from a promise that rates never change.', 'Interest $105 under stated assumptions; APY reflects compounding; variable rate and tax caveats.', 'multiply', ['2500','0.042'])
add('saving', 'I am saving for a rental security deposit due in four months. A colleague suggests putting it all into a volatile stock because savings interest seems small. How should the short deadline change my choice?', 'Capital preservation and liquidity dominate short-horizon required spending; avoid stock-market loss risk; discuss accessible insured savings where applicable without guaranteeing every product.')
add('saving', 'I can save $275 per month for 12 months and already have $900 in a moving fund. Ignoring interest, what total will I have after the final deposit? Mention how to handle uncertain moving costs.', 'Total $4,200; itemized estimates and contingency buffer.', 'sum', ['3300','900'])
add('saving', 'I keep a $2,000 emergency fund at home because I worry I will lose access if a bank app fails. What are the tradeoffs of cash at home versus a regulated deposit account? I have not told you my country.', 'Theft/fire/inflation and access tradeoffs; small physical buffer may coexist with bank savings; deposit insurance limits depend on jurisdiction; ask country, no invented coverage.')
add('saving', 'I took home $2,800 this month and moved $210 into long-term savings. Define savings rate as that transfer divided by take-home pay. What is my savings rate in percent? Avoid implying one month proves my future progress.', '7.50%; stated definition and tracking across months.', 'percent', ['210','2800'])
